<template>
  <div class="organizer-app">
    <aside class="org-sidebar">
      <a class="org-brand" href="#/" @click.prevent="tab='overview'"><span class="brand-mark">R<span>↗</span></span><span>runback<small>TOURNAMENT DESK</small></span></a>
      <div class="event-picker" @keydown.esc="eventMenu=false">
        <span class="nav-label">CURRENT TOURNAMENT</span>
        <button class="event-picker-trigger" :aria-expanded="String(eventMenu)" aria-controls="event-menu" @click="eventMenu=!eventMenu"><span class="event-avatar">{{ event?initials(event.name):'+' }}</span><span><b>{{ event?event.name:'Choose a tournament' }}</b><small>{{ event?eventStatus(event):'Create your first event' }}</small></span><i class="mdi mdi-chevron-down"></i></button>
        <div v-if="eventMenu" class="event-picker-shade" @click="eventMenu=false"></div>
        <section v-if="eventMenu" id="event-menu" class="event-picker-menu" aria-label="Choose a tournament">
          <header><b>Your tournaments</b><button aria-label="Close event menu" @click="eventMenu=false">×</button></header>
          <input v-model="eventSearch" placeholder="Find a tournament…" aria-label="Find a tournament" />
          <div class="event-picker-list"><button v-for="e in pickerEvents" :key="e.id" :class="{chosen:e.id===eventId}" @click="eventId=e.id;selectEvent();eventMenu=false"><span class="event-avatar">{{ initials(e.name) }}</span><span><b>{{ e.name }}</b><small>{{ eventStatus(e) }} · {{ e.entrants.length }} players</small></span><i v-if="e.id===eventId" class="mdi mdi-check"></i></button><p v-if="!pickerEvents.length">No matching tournaments.</p></div>
          <footer><button @click="eventMenu=false;newEvent=true">＋ Create tournament</button><button @click="eventMenu=false;tab='library'">View history →</button></footer>
        </section>
      </div>
      <span class="nav-label">TOURNAMENT</span>
      <nav aria-label="Tournament navigation"><button v-for="item in nav" :key="item.id" :aria-label="item.label" :class="{active:tab===item.id}" @click="tab=item.id;page=1" :aria-current="tab===item.id?'page':null"><i aria-hidden="true" :class="'mdi mdi-'+item.icon"></i>{{ item.label }}<span v-if="item.id==='matches' && ready.length" class="nav-count">{{ ready.length }}</span></button></nav>
      <span class="nav-label">EVENT CONTROL</span>
      <nav aria-label="Event control"><button v-for="item in tools" :key="item.id" :class="{active:tab===item.id}" @click="tab=item.id"><i :class="'mdi mdi-'+item.icon" aria-hidden="true"></i>{{ item.label }}</button></nav>
      <span class="nav-label">WORKSPACE</span>
      <nav class="workspace-links" aria-label="Workspace"><router-link to="/manual"><i class="mdi mdi-monitor"></i>Manual broadcast</router-link><router-link to="/players"><i class="mdi mdi-account-box-multiple-outline"></i>Saved players</router-link><router-link to="/graphics"><i class="mdi mdi-television-play"></i>OBS overlays</router-link><router-link to="/settings"><i class="mdi mdi-cog-outline"></i>App settings</router-link><router-link to="/about"><i class="mdi mdi-information-outline"></i>About & credits</router-link></nav>
      <div class="nav-bottom"><p><b>RUNBACK / T8</b><br>Build by Sheeda Talli<br><span>Original Runback by Opeik</span><small class="build-stamp">DESIGN 03 · CONNECTED BRACKETS</small></p></div>
    </aside>
    <main class="org-main">
      <header class="org-topbar"><span>WORKSPACE <b>/ {{ tabTitle }}</b></span><div><span class="save-state" :class="{offline:!connected}"><i></i>{{ !connected?'Disconnected':busy?'Saving…':'Saved locally' }}</span><button v-if="event" class="btn subtle small delete-event-button" :disabled="busy || !connected" @click="deleteEventDialog=true">Delete event</button><button v-if="event && !event.ended" class="btn subtle small end-event-button" :disabled="busy || !connected" @click="endDialog=true">End tournament</button><button class="btn subtle small" @click="newEvent=true">+ New event</button></div></header>
      <div v-if="error" class="org-alert" role="alert">{{ error }}<button aria-label="Dismiss error" @click="error=''">×</button></div>
      <div v-if="notice" class="org-notice" role="status">{{ notice }}</div>
      <div v-if="!loaded" class="org-content empty-state"><h1>Opening your workspace…</h1><p>Connecting to the local tournament server.</p></div>
      <div v-else-if="!event && !['formats','library','discord'].includes(tab)" class="org-content welcome">
        <span class="eyebrow">LESS ADMIN. MORE GOOD MATCHES.</span><h1>Your tournament.<br>Under control<span>.</span></h1><p>From the first check-in to the final set.<br>A clear home for players, matches and your stream.</p>
        <div class="welcome-actions"><button class="btn primary" @click="newEvent=true">Create a tournament <span>↗</span></button><button class="btn" :disabled="busy || !connected" @click="demo">Try a sample event</button></div>
        <div class="welcome-steps"><article><b>01</b><h3>Pick your format</h3><p>Use a local default or a researched major-event template.</p></article><article><b>02</b><h3>Bring your players</h3><p>Paste a list, check everyone in and arrange your seeds.</p></article><article><b>03</b><h3>Run the room</h3><p>Call matches, report scores and send players straight to OBS.</p></article></div>
        <label class="import-link">Have a Runback event backup? Restore a copy<input type="file" accept="application/json,.json" @change="restore" /></label>
      </div>
      <div v-else class="org-content">
        <EventLibrary v-if="tab==='library'" :events="state.events" @open="openHistoryEvent" @export="exportHistoryEvent" @create="newEvent=true" /><DiscordSetup v-else-if="tab==='discord'" :linked="linkedPlayers" :entrant-count="event?event.entrants.length:0" /><template v-else-if="tab==='formats'"><div class="page-title"><div><span class="eyebrow">LEARN FROM THE BIG STAGES</span><h1>A format for your event.</h1><p>Researched examples, explained simply. Every preset can be reviewed before play.</p></div></div><div class="reference-note">Rules vary by year and game. These are selected format references, not a complete tournament archive or official certification.</div><div class="preset-grid"><article v-for="preset in presets" :key="preset.id" class="org-card preset-card"><span class="eyebrow">{{ preset.tag }}</span><h2>{{ preset.title }}</h2><p>{{ preset.summary }}</p><div class="format-facts"><span>{{ preset.format==='groups'?'3 stages':preset.format==='pools'?'Pools + finals':preset.format==='double'?'2 losses to exit':'1 loss to exit' }}</span><span>FT{{ preset.ft }} → FT{{ preset.finalFt }}</span></div><p class="muted">{{ preset.notes }}</p><a v-if="preset.source" :href="preset.source" target="_blank" rel="noopener noreferrer">{{ preset.sourceLabel }} ↗</a><small v-else>{{ preset.sourceLabel }}</small><button class="btn" @click="create.preset=preset.id;newEvent=true">Use this format</button></article></div></template>
        <template v-else-if="event">
          <div class="page-title"><div><span class="eyebrow">{{ event.ended?'TOURNAMENT ENDED':event.champion?'EVENT COMPLETE':event.started?'TOURNAMENT IN PROGRESS':'GET READY TO PLAY' }}</span><h1>{{ tab==='overview'?event.name:tabTitle }}<span>.</span></h1><p>{{ tabDescription }}</p></div><button v-if="tab==='overview'" class="btn" @click="exportBackup"><i aria-hidden="true" class="mdi mdi-download"></i>Export backup</button></div>
          <section v-if="event.ended" class="ended-banner"><div><b>This tournament has ended.</b><span>Results and bracket are saved. Resume it to keep testing, or create a new event.</span></div><button class="btn primary small" :disabled="busy || !connected" @click="command('resumeEvent')">Resume tournament</button></section>
          <OperationsDesk v-if="tab==='operations'" :key="event.id" :event="event" :state="state" :busy="busy || !connected || !!event.ended" :command="command" @match="openMatch" /><template v-if="tab==='overview'"><section class="easy-start"><div class="easy-start-heading"><div><span class="eyebrow">YOUR TOURNAMENT, STEP BY STEP</span><h2>{{ event.name }} is {{ event.champion?'complete':event.ended?'ended':event.started?'underway':'ready to set up' }}.</h2><p>Choose the next card. Runback will keep your players, matches and results together.</p></div><span class="easy-progress">{{ event.champion?'4':event.started?'3':'1' }} <small>/ 4</small></span></div><div class="easy-steps"><button class="easy-step" :class="{done:checked.length>=2,selected:!event.started}" @click="tab='players'"><span class="step-number">1</span><span><b>Add players</b><small>{{ event.started?event.entrants.length+' players in the bracket':checked.length+' checked in · '+event.entrants.length+' added' }}</small></span><strong>{{ event.started?'View':'Open' }} →</strong></button><button class="easy-step" :class="{done:event.started,selected:event.started&&!event.champion}" @click="tab=event.started?'bracket':'players'"><span class="step-number">2</span><span><b>{{ event.started?'Bracket ready':'Make the bracket' }}</b><small>{{ event.started?'See who plays next':'Check in at least 2 players, then choose Generate bracket' }}</small></span><strong>{{ event.started?'View':'Set up' }} →</strong></button><button class="easy-step" :class="{done:!!event.champion,selected:event.started&&!event.champion}" @click="tab=event.started?'matches':'players'"><span class="step-number">3</span><span><b>Play matches</b><small>{{ event.started?ready.length+' ready · '+playing.length+' playing · '+done.length+' finished':'Your match queue opens after bracket creation' }}</small></span><strong>{{ event.started?'Open':'Next' }} →</strong></button><button class="easy-step" :class="{done:!!event.champion}" @click="tab='results'"><span class="step-number">4</span><span><b>Finish &amp; see results</b><small>{{ event.champion?'Champion: '+name(event.champion):'Placements appear here when the event is complete' }}</small></span><strong>View →</strong></button></div><p v-if="event.ended" class="easy-help">This tournament is ended. Its history and results are saved. Use “Resume tournament” above to continue testing.</p><p v-else-if="!event.started" class="easy-help">First time? Click <b>Add players</b>, add or import your entrants, check in the players who arrived, then press <b>Generate bracket</b>.</p></section><details class="overview-details" open><summary>Event activity & statistics</summary><section class="event-marquee"><div><span class="eyebrow">TEKKEN 8 / TOURNAMENT CONTROL</span><h2>Every set. Every station.<br>One clear view.</h2><p>{{ event.venue || 'Your next great tournament starts here' }} <span v-if="event.date">· {{ event.date }}</span></p><button class="btn" @click="tab='operations'">Open operations ↗</button></div><div class="marquee-progress"><b>{{ completion }}<small>%</small></b><span>OF POSSIBLE SETS COMPLETE</span><div class="marquee-track"><i :style="{width:completion+'%'}"></i></div></div></section>
            <div class="stat-grid"><article><span>PLAYERS CHECKED IN</span><b>{{ checked.length }}<small>/ {{ event.entrants.length }}</small></b><div>{{ event.started?'Bracket locked':'Registration open' }}</div></article><article><span>READY TO PLAY</span><b>{{ ready.length.toString().padStart(2,'0') }}</b><div>{{ playing.length }} matches in progress</div></article><article><span>STATIONS AVAILABLE</span><b>{{ freeStations.length.toString().padStart(2,'0') }}<small>/ {{ event.stations.length }}</small></b><div>Assign a ready match below</div></article><article><span>MATCHES COMPLETE</span><b>{{ done.length.toString().padStart(2,'0') }}</b><div>{{ event.matches.filter(m=>m.status!=='bye' && m.status!=='skipped').length }} possible sets</div></article></div>
            <div class="overview-grid"><div>
              <section class="org-card next-step"><span class="eyebrow">{{ event.ended?'EVENT STATUS':event.champion?'YOUR CHAMPION':'YOUR NEXT STEP' }}</span><template v-if="event.ended"><h2>Tournament ended.</h2><p>Your bracket, players and recorded results remain saved. Resume this event or create a separate tournament.</p><button class="btn primary" :disabled="busy || !connected" @click="command('resumeEvent')">Resume tournament</button></template><template v-else-if="event.champion"><h2>🏆 {{ name(event.champion) }}</h2><p>The bracket is complete. Export the standings and save an event backup.</p><button class="btn primary" @click="tab='results'">View results ↗</button></template><template v-else-if="!event.started"><h2>{{ checked.length>=2?'Your bracket is almost ready.':'Let’s get your players in.' }}</h2><p>{{ checked.length>=2?'Review your seeds and checked-in players, then generate the bracket. Unchecked players will sit this event out.':'Add names individually or paste a list of players. Check players in when they arrive.' }}</p><button class="btn primary" @click="tab='players'">{{ checked.length>=2?'Review players & start':'Add your players' }} ↗</button></template><template v-else-if="ready[0]"><h2>{{ name(ready[0].players[0]) }} <em>vs</em> {{ name(ready[0].players[1]) }}</h2><p>{{ ready[0].id }} · {{ ready[0].section }} · {{ ready[0].label }} · First to {{ ready[0].ft }}</p><button class="btn primary" @click="openMatch(ready[0])">Run this match ↗</button><button class="org-link-button" @click="tab='matches'">See all ready matches</button></template><template v-else><h2>Matches are in progress.</h2><p>Report the completed sets to advance the bracket.</p><button class="btn primary" @click="tab='matches'">Open match queue ↗</button></template></section>
              <section class="org-card"><div class="section-title"><h2>On the floor</h2><button class="org-link-button" @click="tab='matches'">All matches →</button></div><div v-if="!playing.length" class="small-empty">No matches called yet. Assign a station from the match queue.</div><button v-for="m in playing" :key="m.id" class="floor-row" @click="openMatch(m)"><span class="station-icon"><i aria-hidden="true" class="mdi mdi-monitor"></i></span><span><b>{{ name(m.players[0]) }} vs {{ name(m.players[1]) }}</b><small>{{ m.station }} · {{ m.label }}</small></span><strong>{{ m.scores[0] }} : {{ m.scores[1] }}</strong><span>→</span></button></section>
            </div><div><section class="org-card checklist"><div class="section-title"><h2>Before you start</h2><span>{{ checklistCount }}/5</span></div><label v-for="item in checklist" :key="item.id"><input type="checkbox" :checked="event.checklist[item.id]" :disabled="busy || !connected" @change="command('checklist',{key:item.id,value:$event.target.checked})"/><span>{{ item.label }}</span></label></section><section class="org-card"><div class="section-title"><h2>Event at a glance</h2></div><dl class="event-facts"><dt>Format</dt><dd>{{ formatName }}</dd><dt>Set length</dt><dd>First to {{ event.ft }} · finals {{ event.finalFt }}</dd><dt>Location</dt><dd>{{ event.venue || 'Not set' }}</dd><dt>Date</dt><dd>{{ event.date || 'Not set' }}</dd></dl><button class="org-link-button" @click="tab='setup'">View event settings →</button></section></div></div>
          </details></template>
          <template v-if="tab==='players'">
            <section v-if="!event.started" class="org-card"><form class="add-player-form" @submit.prevent="addPlayer"><label>Player name<input v-model="playerForm.name" required maxlength="64" placeholder="Gamertag" /></label><label>Team <small>optional</small><input v-model="playerForm.team" maxlength="30" placeholder="Team / sponsor" /></label><label>Country <small>optional</small><input v-model="playerForm.country" maxlength="2" placeholder="PK" /></label><label>Discord user ID <small>optional · for automatic calls</small><input v-model="playerForm.discordId" inputmode="numeric" maxlength="20" placeholder="123456789012345678" /></label><button class="btn primary" :disabled="busy || !connected">Add player</button></form><details class="bulk-import"><summary>Import a player list or use saved players</summary><p>Paste one name per line, or CSV with columns <b>name, team, country, discord_id</b>. The fourth column links the player's Discord account. A 17–20 digit Discord user ID is needed for a personal ping. Import follows your list order as the initial seeding.</p><textarea v-model="bulk" rows="5" placeholder="name,team,country,discord_id&#10;Player One,Team A,PK,123456789012345678&#10;Player Two,Team B,JP,"></textarea><div class="button-row"><button class="btn" :disabled="busy || !bulk.trim()" @click="importPlayers">Add pasted players</button><label class="btn file-button">Choose CSV / TXT<input type="file" accept=".csv,.txt" @change="readRoster" /></label><button class="btn" :disabled="busy || !savedPlayers.length" @click="importSaved">Import saved player library ({{ savedPlayers.length }})</button></div></details></section>
            <section class="org-card"><div class="section-title"><h2>Registration <span class="badge">{{ event.entrants.length }}</span></h2><div class="button-row"><button v-if="!event.started && event.entrants.length" class="org-link-button" :disabled="busy" @click="command('checkAll')">Check in all</button><button v-if="!event.started" class="btn primary" :disabled="busy || checked.length<(event.format==='pools'?4:2)" @click="startDialog=true">{{ event.format==='pools'?'Create pools':'Generate bracket' }}</button><span v-else class="status-pill">Bracket locked</span></div></div><div class="table-toolbar"><input class="search" v-model="search" @input="page=1" placeholder="Search players or teams…" aria-label="Search players"/><span class="muted">{{ checked.length }} checked in · {{ event.entrants.length-checked.length }} not here yet · {{ linkedPlayers }} Discord linked</span></div><div class="table-scroll"><table><thead><tr><th>SEED</th><th>PLAYER</th><th>TEAM</th><th>COUNTRY</th><th>DISCORD</th><th>CHECK-IN</th><th v-if="!event.started">ACTIONS</th></tr></thead><tbody><tr v-for="p in playerPage" :key="p.id"><td><button v-if="!event.started" class="seed-button" :aria-label="'Change seed for '+p.name" @click="seedPlayer=p.id;seedPosition=event.entrants.indexOf(p)+1">{{ event.entrants.indexOf(p)+1 }}</button><span v-else>{{ event.entrants.indexOf(p)+1 }}</span></td><td class="player-cell"><span class="avatar">{{ initials(p.name) }}</span><b>{{ p.name }}</b></td><td>{{ p.team || '—' }}</td><td>{{ p.country || '—' }}</td><td><span class="status-pill" :class="p.discordId?'discord-linked':''">{{ p.discordId?'Linked':'—' }}</span></td><td><label class="checkin-toggle"><input type="checkbox" :checked="p.checked" :disabled="event.started || busy" @change="command('checkin',{playerId:p.id,checked:$event.target.checked})"/>{{ p.checked?'Here':'Not yet' }}</label></td><td v-if="!event.started"><button class="org-link-button" @click="editEntry = { ...p, playerId:p.id }" :disabled="busy">Edit</button> · <button class="org-link-button danger" @click="removePlayer=p" :disabled="busy">Remove</button></td></tr><tr v-if="!filteredPlayers.length"><td colspan="7" class="small-empty">{{ search?'No players match your search.':'No players yet. Add your first player above.' }}</td></tr></tbody></table></div><div class="pagination"><span>{{ filteredPlayers.length }} players · page {{ page }} / {{ Math.max(1,Math.ceil(filteredPlayers.length/24)) }}</span><div><button class="btn small" :disabled="page<=1" @click="page--">Previous</button><button class="btn small" :disabled="page*24>=filteredPlayers.length" @click="page++">Next</button></div></div></section>
          </template>
          <template v-if="tab==='matches'">
            <div class="station-strip"><div v-for="station in event.stations" :key="station" :class="{occupied:occupied(station)}"><i aria-hidden="true" class="mdi mdi-monitor"></i><span><b>{{ station }}</b><small>{{ occupied(station)?'In use':'Available' }}</small></span></div></div>
            <section class="org-card"><div class="table-toolbar"><div class="segmented"><button v-for="s in ['ready','playing','done','all']" :key="s" :class="{selected:matchFilter===s}" @click="matchFilter=s;page=1">{{ {ready:'Ready',playing:'In progress',done:'Completed',all:'All matches'}[s] }}</button></div><input class="search" v-model="matchSearch" @input="page=1" placeholder="Player, round or match ID…" aria-label="Search matches"/></div><div v-if="!event.started" class="small-empty">Generate a bracket from Players to create your match queue.</div><div v-else-if="!filteredMatches.length" class="small-empty">No matches in this view. Try another filter.</div><div class="match-list"><article v-for="m in matchPage" :key="m.id" class="match-row"><div class="match-id">{{ m.id }}<small>FT{{ m.ft }}</small></div><div class="match-names"><b><span class="side-tag">P1</span>{{ name(m.players[0]) }} <em>vs</em> <span class="side-tag p2">P2</span>{{ name(m.players[1]) }}</b><small>{{ m.section }} · {{ m.label }}</small></div><span class="match-score">{{ m.scores.join(' : ') }}</span><span class="status-pill" :class="m.status">{{ statusLabel(m) }}</span><button v-if="['ready','playing'].includes(m.status)" class="btn small" :disabled="busy" @click="swapSides(m)" title="Swap P1 and P2">⇄ Switch sides</button><button class="btn small" :disabled="!['ready','playing','done'].includes(m.status)" @click="openMatch(m)">{{ m.status==='done'?'Details':'Open match' }} →</button></article></div><div class="pagination"><span>{{ filteredMatches.length }} matches · page {{ page }} / {{ Math.max(1,Math.ceil(filteredMatches.length/24)) }}</span><div><button class="btn small" :disabled="page<=1" @click="page--">Previous</button><button class="btn small" :disabled="page*24>=filteredMatches.length" @click="page++">Next</button></div></div></section>
          </template>
          <template v-if="tab==='bracket'">
            <div class="table-toolbar bracket-toolbar"><select v-model="bracketSection" aria-label="Bracket section"><option value="">All sections</option><option v-for="s in sections" :key="s">{{ s }}</option></select><p class="muted">P1 is the left-side player; P2 is the right-side player. Switch sides before or during a set. Results advance automatically.</p></div><section v-if="!event.started" class="org-card small-empty">Your bracket will appear after check-in and seeding.</section><section v-if="event.format==='pools'" class="pool-stages"><div class="pool-stage-heading"><div><span class="eyebrow">PHASE 1 · ROUND-ROBIN POOLS</span><h2>Pool standings</h2><p>Everyone plays each player in their pool. Wins rank first; game difference breaks ties, then original seed.</p></div><span class="status-pill">Top {{ event.poolAdvance||2 }} from every pool advance</span></div><article v-for="pool in poolTables" :key="pool.name" class="pool-board"><header><b>Pool {{ pool.name }}</b><span>{{ pool.complete?'Complete':pool.done+' / '+pool.matches.length+' matches played' }}</span></header><div class="table-scroll"><table><thead><tr><th>PLACE</th><th>PLAYER</th><th>SETS WON</th><th>SETS LOST</th><th>GAME DIFF</th><th>ADVANCEMENT</th></tr></thead><tbody><tr v-for="(player,index) in pool.players" :key="player.id" :class="{qualifies:index<(event.poolAdvance||2)}"><td>{{ index+1 }}</td><td><b>{{ name(player.id) }}</b></td><td>{{ player.wins }}</td><td>{{ player.losses }}</td><td>{{ player.gameDiff>0?'+':'' }}{{ player.gameDiff }}</td><td>{{ index<(event.poolAdvance||2)?'Advances to finals':'Remains in pool' }}</td></tr></tbody></table></div></article></section><BracketTree v-if="event.started" :key="event.id" :event="event" :section="bracketSection" @open="openMatch" /><section v-if="event.started" class="share-link-panel"><div><b>Share this live bracket</b><p>Copy the link into Discord. For people outside your computer, use a public hostname or tunnel that reaches this Runback server.</p></div><label>Public server URL (optional)<input v-model="publicBase" placeholder="https://your-public-runback-address" @change="savePublicBase" /></label><div class="share-url-row"><code>{{ publicBracketUrl }}</code><button class="btn small primary" @click="copyBracketUrl">{{ bracketCopied?'Copied':'Copy live link' }}</button><button class="btn small" @click="openBracketUrl">Preview</button></div></section>
          </template>
          <template v-if="tab==='stream'">
            <div class="overview-grid"><section class="org-card"><span class="eyebrow">OBS BROWSER SOURCE</span><h2>One match. Ready for air.</h2><p>Send a match from the queue. Its players, stage and saved scores update the existing overlay.</p><div class="source-url"><code>{{ overlayUrl }}</code><button class="btn small" @click="copyUrl">{{ copied?'Copied':'Copy URL' }}</button></div><p class="muted">1920 × 1080 · 60 FPS · keep Runback open</p><template v-if="liveMatch"><div class="stream-match"><span class="status-pill playing">SELECTED FOR STREAM</span><h2>{{ name(liveMatch.players[0]) }} <em>vs</em> {{ name(liveMatch.players[1]) }}</h2><div class="stream-score">{{ liveMatch.scores[0] }} <em>:</em> {{ liveMatch.scores[1] }}</div><p>{{ liveMatch.section }} · {{ liveMatch.label }} · FT{{ liveMatch.ft }}</p><button class="btn primary" @click="openMatch(liveMatch)">Open score controls</button></div></template><div v-else class="small-empty">No match from this event is selected. Open a ready match and choose “Send to OBS”.</div></section><section class="org-card"><h2>Stream checklist</h2><ol class="stream-steps"><li>Add an OBS Browser Source using the URL.</li><li>Set the source to 1920 × 1080.</li><li>Open a match and send it to OBS.</li><li>Save live scores after each game.</li><li>Report the final result to advance the bracket.</li></ol><div class="reference-note">Set scores are separate from in-game round wins. The overlay still leaves the round indicators clear.</div><router-link class="org-link-button" to="/manual">Commentators & manual controls →</router-link></section></div>
          </template>
          <template v-if="tab==='results'">
            <section class="org-card"><div class="section-title"><h2>{{ event.champion?'Final standings':'Tournament results' }}</h2><button class="btn" :disabled="!rankings.length" @click="exportResults">Export CSV</button></div><div v-if="!rankings.length" class="small-empty">Final placements appear when the tournament is complete. Completed match results are available in Matches.</div><table v-else><thead><tr><th>PLACE</th><th>PLAYER</th><th>SET WINS</th><th>SET LOSSES</th></tr></thead><tbody><tr v-for="r in rankings" :key="r.id"><td><b>{{ r.place===1?'🏆 1':r.place }}</b></td><td>{{ name(r.id) }}</td><td>{{ r.wins }}</td><td>{{ r.losses }}</td></tr></tbody></table></section><section class="org-card"><div class="section-title"><h2>Activity log</h2><button class="btn small" :disabled="busy || !event.results.length" @click="undoDialog=true">Undo latest result</button></div><p class="muted">Undo is available for the most recently reported result. Release dependent matches first.</p><div v-for="(h,i) in event.history.slice(0,40)" :key="i" class="activity-row"><time>{{ time(h.at) }}</time><span>{{ h.text }}</span></div></section>
          </template>
          <template v-if="tab==='setup'">
            <div class="overview-grid"><form class="org-card settings-form" @submit.prevent="saveSettings"><h2>Event details</h2><label>Event name<input v-model="settingsForm.name" required maxlength="100" :disabled="event.started" /></label><div class="field-pair"><label>Venue<input v-model="settingsForm.venue" maxlength="100" :disabled="event.started" placeholder="Venue or online" /></label><label>Date<input type="date" v-model="settingsForm.date" :disabled="event.started" /></label></div><label>Stations <small>one name per line · shared across this workspace</small><textarea v-model="stationText" rows="4" :disabled="event.started"></textarea></label><details><summary>Advanced format settings</summary><label>Bracket format<select v-model="settingsForm.format" :disabled="event.started"><option value="double">Double elimination</option><option value="single">Single elimination</option><option value="groups">Two GSL phases → knockout (32 players)</option><option value="pools">Round-robin pools → finals</option></select></label><div v-if="settingsForm.format==='pools'" class="field-pair"><label>Number of pools <small>0 = automatic · about 8 per pool</small><input v-model.number="settingsForm.poolCount" type="number" min="0" max="64" :disabled="event.started" /></label><label>Players advancing from each pool<select v-model.number="settingsForm.poolAdvance" :disabled="event.started"><option :value="1">Top 1</option><option :value="2">Top 2</option><option :value="3">Top 3</option><option :value="4">Top 4</option></select></label><label>Final bracket<select v-model="settingsForm.finalFormat" :disabled="event.started"><option value="double">Double elimination</option><option value="single">Single elimination</option></select></label></div><div class="field-pair"><label>Games to win a set<input v-model.number="settingsForm.ft" type="number" min="1" max="9" :disabled="event.started" /></label><label>Games to win finals<input v-model.number="settingsForm.finalFt" type="number" min="1" max="9" :disabled="event.started" /></label></div><label v-if="settingsForm.format==='double'">Longer sets begin at<select v-model="settingsForm.longSets" :disabled="event.started"><option value="finals">Winners final, losers final, grand final</option><option value="top4">Top 4 (also includes losers semifinal)</option><option value="top8">Top 8</option></select></label></details><button v-if="!event.started" class="btn primary" :disabled="busy">Save settings</button><p v-else class="reference-note">Settings and seeding are locked while this bracket is running.</p></form><div><section class="org-card"><span class="eyebrow">STARTING TEMPLATE</span><h2>{{ currentPreset.title }}</h2><p>{{ currentPreset.summary }}</p><p class="muted">{{ currentPreset.notes }}</p><a v-if="currentPreset.source" :href="currentPreset.source" target="_blank" rel="noopener noreferrer">Read the source rules ↗</a></section><section class="org-card"><h2>Keep a backup</h2><p>Events save on this computer. Export a file before the event and after important rounds.</p><button class="btn" @click="exportBackup">Export this event</button><label class="import-link">Restore a backup as a new event<input type="file" accept=".json" @change="restore" /></label></section></div></div>
          </template>
        </template>
      </div>
    </main>
    <div v-if="newEvent" class="modal-backdrop" @click.self="newEvent=false"><form class="org-modal" role="dialog" aria-modal="true" aria-labelledby="new-title" @submit.prevent="createEvent"><button type="button" class="modal-close" @click="newEvent=false" aria-label="Close">×</button><span class="eyebrow">A FRESH BRACKET STARTS HERE</span><h2 id="new-title">Create your tournament.</h2><label>Event name<input v-model="create.name" maxlength="100" placeholder="Saturday Night Tekken" required autofocus /></label><label>Starting format<select v-model="create.preset"><option v-for="p in presets" :key="p.id" :value="p.id">{{ p.title }}</option></select></label><p class="reference-note">{{ selectedPreset.summary }}</p><p class="muted">{{ selectedPreset.notes }}</p><div class="field-pair"><label>Venue<input v-model="create.venue" placeholder="Venue or online" /></label><label>Date<input type="date" v-model="create.date" /></label></div><button class="btn primary" :disabled="busy || !connected">Create event →</button></form></div>
    <div v-if="startDialog && event" class="modal-backdrop"><section class="org-modal" role="dialog" aria-modal="true" aria-labelledby="start-title"><h2 id="start-title">{{ event.format==='pools'?'Ready to create pools?':'Ready to generate the bracket?' }}</h2><p><b>{{ checked.length }} checked-in players</b> will enter in seed order. {{ event.entrants.length-checked.length }} unchecked players will be excluded.</p><p>{{ formatName }} · FT{{ event.ft }} / finals FT{{ event.finalFt }}<span v-if="event.format==='pools'"> · {{ event.poolCount||'Automatic' }} pools · top {{ event.poolAdvance||2 }} advance</span></p><p class="reference-note">Entrants and format lock once generated. Check the seed order now.</p><div class="button-row"><button class="btn" @click="startDialog=false">Back to players</button><button class="btn primary" :disabled="busy" @click="startEvent">Generate bracket</button></div></section></div>
    <div v-if="selectedMatch && event" class="modal-backdrop" @click.self="matchId=''">
      <section class="org-modal match-modal" role="dialog" aria-modal="true" aria-labelledby="match-title"><button class="modal-close" aria-label="Close match" @click="matchId=''">×</button><span class="eyebrow">{{ selectedMatch.id }} · {{ selectedMatch.section }}</span><h2 id="match-title">{{ selectedMatch.label }}</h2><p>First to {{ selectedMatch.ft }} games · {{ statusLabel(selectedMatch) }}</p><div class="score-controls"><div v-for="i in [0,1]" :key="i" :class="'score-side side-'+i"><span><span class="side-tag" :class="{p2:i===1}">P{{ i+1 }}</span> {{ name(selectedMatch.players[i]) }}</span><div><button class="step-button" :disabled="scores[i]<=0 || selectedMatch.status==='done'" @click="$set(scores,i,scores[i]-1)" :aria-label="'Decrease '+name(selectedMatch.players[i])">−</button><input type="number" v-model.number="scores[i]" :min="0" :max="selectedMatch.ft" :disabled="selectedMatch.status==='done'" :aria-label="'Score for '+name(selectedMatch.players[i])"/><button class="step-button" :disabled="scores[i]>=selectedMatch.ft || selectedMatch.status==='done'" @click="$set(scores,i,scores[i]+1)" :aria-label="'Increase '+name(selectedMatch.players[i])">+</button></div></div></div><button v-if="['ready','playing'].includes(selectedMatch.status)" class="org-link-button swap-modal" :disabled="busy" @click="swapSides(selectedMatch)">⇄ Switch P1 and P2 sides</button>
        <template v-if="selectedMatch.status!=='done'"><div class="station-assignment"><label>Play station<select v-model="station"><option value="">Choose a station</option><option v-for="s in event.stations" :key="s" :disabled="occupied(s) && selectedMatch.station!==s">{{ s }}</option></select></label><button class="btn" :disabled="busy || !station" @click="command('assign',{matchId,station})">Call players</button><button v-if="selectedMatch.status==='playing'" class="org-link-button" :disabled="busy" @click="command('release',{matchId})">Release</button></div><div class="button-row"><button class="btn" :disabled="busy" @click="command('stream',{matchId})"><i aria-hidden="true" class="mdi mdi-monitor"></i>{{ event.streamMatch===matchId?'Refresh OBS':'Send to OBS' }}</button><button class="btn" :disabled="busy" @click="saveScore">Save live score</button><button class="btn primary" :disabled="busy || !validResult" @click="reportDialog=true">Report result →</button></div><details class="forfeit"><summary>Player missing or disqualified?</summary><label>Forfeiting player<select v-model="forfeit"><option :value="-1">Choose a player</option><option v-for="i in [0,1]" :key="i" :value="i">{{ name(selectedMatch.players[i]) }}</option></select></label><label>Reason<input v-model="forfeitReason" maxlength="160" placeholder="e.g. No-show after final call"/></label><button class="btn" :disabled="busy || forfeit<0 || !forfeitReason.trim()" @click="reportDialog=true">Review forfeit</button></details></template><p v-else>{{ selectedMatch.reason || 'Result recorded.' }} Winner: <b>{{ name(selectedMatch.winner) }}</b></p>
      </section>
    </div>
    <div v-if="reportDialog && selectedMatch" class="modal-backdrop confirm-layer"><section class="org-modal" role="dialog" aria-modal="true" aria-labelledby="report-title"><h2 id="report-title">Confirm the result.</h2><p><b>{{ name(selectedMatch.players[forfeit>=0?1-forfeit:scores[0]>scores[1]?0:1]) }}</b> wins {{ forfeit>=0?'by forfeit':scores.join(' – ') }}.</p><p>{{ forfeit>=0?forfeitReason:'The winner advances and the station becomes available.' }}</p><div class="button-row"><button class="btn" @click="reportDialog=false">Go back</button><button class="btn primary" :disabled="busy" @click="reportResult">Confirm result</button></div></section></div>
    <div v-if="endDialog && event" class="modal-backdrop confirm-layer"><section class="org-modal" role="dialog" aria-modal="true" aria-labelledby="end-title"><h2 id="end-title">End this tournament?</h2><p>This ends <b>{{ event.name }}</b> now. Saved players, bracket and reported results will stay in your workspace. Any match on a station will be released, and no more scores or match calls can be recorded until you resume the event.</p><div class="button-row"><button class="btn" @click="endDialog=false">Keep running</button><button class="btn danger-action" :disabled="busy || !connected" @click="endTournament">End tournament</button></div></section></div>
    <div v-if="deleteEventDialog && event" class="modal-backdrop confirm-layer"><section class="org-modal" role="dialog" aria-modal="true" aria-labelledby="delete-event-title"><span class="eyebrow">PERMANENT EVENT REMOVAL</span><h2 id="delete-event-title">Delete “{{ event.name }}”?</h2><p>This permanently removes its players, bracket, results, schedule and event history from this Runback workspace. Export a backup first if you may need it later.</p><div class="button-row"><button class="btn" @click="deleteEventDialog=false">Keep event</button><button class="btn danger-action" :disabled="busy || !connected" @click="deleteTournament">Delete event and its data</button></div></section></div>
    <div v-if="editEntry" class="modal-backdrop"><form class="org-modal" role="dialog" aria-modal="true" aria-label="Edit player" @submit.prevent="editPlayer"><h2>Edit player</h2><label>Player name<input v-model="editEntry.name" required maxlength="64" /></label><label>Team<input v-model="editEntry.team" maxlength="30" /></label><label>Country code<input v-model="editEntry.country" maxlength="2" /></label><label>Discord user ID<input v-model="editEntry.discordId" maxlength="20" inputmode="numeric" placeholder="17–20 digit ID" /></label><p class="muted">Players can also link themselves with the Discord <b>/runback link</b> command.</p><div class="button-row" style="margin-top:24px"><button type="button" class="btn" @click="editEntry=null">Cancel</button><button class="btn primary" :disabled="busy">Save player</button></div></form></div>
    <div v-if="seedPlayer" class="modal-backdrop"><form class="org-modal" role="dialog" aria-modal="true" @submit.prevent="changeSeed"><h2>Change seed</h2><label>New position<input type="number" v-model.number="seedPosition" :min="1" :max="event?event.entrants.length:512" required /></label><div class="button-row"><button type="button" class="btn" @click="seedPlayer=''">Cancel</button><button class="btn primary" :disabled="busy">Move player</button></div></form></div>
    <div v-if="removePlayer" class="modal-backdrop"><section class="org-modal" role="dialog" aria-modal="true"><h2>Remove {{ removePlayer.name }}?</h2><p>This removes them from this event’s registration.</p><div class="button-row"><button class="btn" @click="removePlayer=null">Cancel</button><button class="btn primary" :disabled="busy" @click="deletePlayer">Remove player</button></div></section></div>
    <div v-if="undoDialog" class="modal-backdrop"><section class="org-modal" role="dialog" aria-modal="true"><h2>Undo the latest result?</h2><p>Its dependent bracket slots will be recalculated. Any dependent match on a station must be released first.</p><div class="button-row"><button class="btn" @click="undoDialog=false">Cancel</button><button class="btn primary" :disabled="busy" @click="undo">Undo result</button></div></section></div>
  </div>
</template>

<script lang="ts">
import { Vue, Component, Watch } from "vue-property-decorator"
import { Organizer, Event as TournamentEvent, Entrant, Match, PRESETS, emptyOrganizer, standings } from "src/extension/organizer/engine"
import "./organizer.css"
import OperationsDesk from "./operations.vue"
import EventLibrary from "./event-library.vue"
import "./operations.css"
import DiscordSetup from "./discord-setup.vue"
import BracketTree from "./bracket-tree.vue"


@Component({components:{OperationsDesk,EventLibrary,DiscordSetup,BracketTree}})
export default class OrganizerDesk extends Vue {
  state: Organizer=emptyOrganizer();loaded=false;connected=true;busy=false;error="";notice="";eventId="";tab="overview";page=1;search="";matchSearch="";matchFilter="ready";bracketSection="";copied=false;bracketCopied=false;publicBase=""
  eventMenu=false;eventSearch=""
  editEntry:any=null;newEvent=false;startDialog=false;reportDialog=false;undoDialog=false;endDialog=false;deleteEventDialog=false;advanced=false
  create={name:"",preset:"local",venue:"",date:"",poolCount:0,poolAdvance:2,finalFormat:"double"};playerForm={name:"",team:"",country:"",discordId:""};bulk="";stationText=""
  settingsForm:any={};seedPlayer="";seedPosition=1;removePlayer:Entrant|null=null;matchId="";scores=[0,0];station="";forfeit=-1;forfeitReason=""
  rep:any=null;noticeTimer:any=null;editRevision=0;settingsRevision=0;previousFocus:HTMLElement|null=null
  presets=PRESETS
  nav=[{id:"overview",label:"Home",icon:"home-outline"},{id:"players",label:"Players",icon:"account-multiple-outline"},{id:"matches",label:"Play matches",icon:"play-circle-outline"},{id:"bracket",label:"Bracket",icon:"tournament"},{id:"results",label:"Results",icon:"trophy-outline"},{id:"library",label:"History",icon:"history"}]
  tools=[{id:"setup",label:"Event setup",icon:"tune"},{id:"operations",label:"Venue & schedule",icon:"calendar-clock"},{id:"stream",label:"Live broadcast",icon:"access-point"},{id:"discord",label:"Discord connection",icon:"message-outline"},{id:"formats",label:"Format library",icon:"view-grid-outline"}]
  get pickerEvents():TournamentEvent[]{return this.state.events.filter(e=>e.name.toLowerCase().includes(this.eventSearch.toLowerCase())).slice().reverse()}
  eventStatus(e:TournamentEvent):string{return e.champion?"Completed":e.ended?"Ended":e.started?"In progress":"Registration open"}
  checklist=[{id:"rules",label:"Rules shared with players"},{id:"controllers",label:"Controllers & game version checked"},{id:"stations",label:"Stations named and tested"},{id:"stream",label:"OBS overlay tested"},{id:"backup",label:"Event backup exported"}]
  get event():TournamentEvent|undefined{return this.state.events.find(e=>e.id===this.eventId)}
  get tabTitle():string{return ([...this.nav,...this.tools].find(n=>n.id===this.tab)||{label:this.tab==="setup"?"Event setup":this.tab==="discord"?"Discord bot setup":"Format library"}).label}
  get tabDescription():string{return ({overview:"Everything you need to keep the event moving.",players:"Add entrants, check them in and arrange seeds. Only checked-in players enter the bracket.",matches:"Call players, assign stations and report completed sets.",bracket:"Follow the tournament from opening matches to the final.",stream:"Connect the match queue to your Tekken 8 broadcast.",results:"Placements, exports and a clear record of what happened.",operations:"Plan the day, manage the floor and coordinate the broadcast.",setup:"Set the event up once. Keep match day simple."} as Record<string,string>)[this.tab]||""}
  get completion():number{return this.event&&this.event.started?Math.round(this.done.length/Math.max(1,this.event.matches.filter(m=>!["bye","skipped"].includes(m.status)).length)*100):0}
  get checked():Entrant[]{return this.event?this.event.entrants.filter(p=>p.checked):[]}
  get linkedPlayers():number{return this.event?this.event.entrants.filter(p=>p.discordId).length:0}
  get ready():Match[]{return this.event?this.event.matches.filter(m=>m.status==="ready"):[]}
  get playing():Match[]{return this.event?this.event.matches.filter(m=>m.status==="playing"):[]}
  get done():Match[]{return this.event?this.event.matches.filter(m=>m.status==="done"):[]}
  get freeStations():string[]{return this.event?this.event.stations.filter(s=>!this.occupied(s)):[]}
  get checklistCount():number{return this.event?Object.values(this.event.checklist).filter(Boolean).length:0}
  get formatName():string{return this.event?({double:"Double elimination",single:"Single elimination",groups:"GSL groups → knockout",pools:"Round-robin pools → finals"})[this.event.format]:""}
  get filteredPlayers():Entrant[]{return this.event?this.event.entrants.filter(p=>(p.name+" "+p.team).toLowerCase().includes(this.search.toLowerCase())):[]}
  get playerPage():Entrant[]{return this.filteredPlayers.slice((this.page-1)*24,this.page*24)}
  get filteredMatches():Match[]{return this.event?this.event.matches.filter(m=>(this.matchFilter==="all"||m.status===this.matchFilter)&&(m.id+" "+m.section+" "+m.label+" "+m.players.map(this.name).join(" ")).toLowerCase().includes(this.matchSearch.toLowerCase())):[]}
  get matchPage():Match[]{return this.filteredMatches.slice((this.page-1)*24,this.page*24)}
  get sections():string[]{return this.event?Array.from(new Set(this.event.matches.map(m=>m.section))):[]}
  get poolTables():Array<{name:string;matches:Match[];done:number;complete:boolean;players:Array<{id:string;wins:number;losses:number;gameDiff:number;seed:number}>}>{
    if(!this.event||this.event.format!=="pools")return []
    const names=Array.from(new Set(this.event.matches.filter(m=>m.section.startsWith("Pool ")).map(m=>m.section.slice(5))))
    return names.map(name=>{
      const matches=this.event!.matches.filter(m=>m.section===`Pool ${name}`)
      const ids=Array.from(new Set(matches.flatMap(m=>m.players.filter(Boolean))))
      const players=ids.map(id=>({id,wins:matches.filter(m=>m.status==="done"&&m.winner===id).length,losses:matches.filter(m=>m.status==="done"&&m.loser===id).length,gameDiff:matches.reduce((diff,m)=>{const i=m.players.indexOf(id);return i<0||m.status!=="done"?diff:diff+(m.scores[i]||0)-(m.scores[1-i]||0)},0),seed:this.event!.entrants.findIndex(p=>p.id===id)})).sort((a,b)=>b.wins-a.wins||b.gameDiff-a.gameDiff||a.seed-b.seed)
      const done=matches.filter(m=>m.status==="done").length
      return {name,matches,done,complete:matches.length>0&&done===matches.length,players}
    })
  }
  get bracketColumns():Array<{key:string;section:string;round:number;roundLabel:string;matches:Match[]}>{
    const columns:Array<{key:string;section:string;round:number;roundLabel:string;matches:Match[]}>=[]
    if(this.event)this.event.matches.filter(m=>!this.bracketSection||m.section===this.bracketSection).forEach(m=>{const key=m.section+"/"+m.round;let c=columns.find(x=>x.key===key);if(!c){c={key,section:m.section,round:m.round,roundLabel:m.label,matches:[]};columns.push(c)}c.matches.push(m)})
    return columns
  }
  get selectedMatch():Match|undefined{return this.event?this.event.matches.find(m=>m.id===this.matchId):undefined}
  get liveMatch():Match|undefined{return this.event?this.event.matches.find(m=>m.id===this.event!.streamMatch):undefined}
  get rankings(){return this.event?standings(this.event):[]}
  get currentPreset(){return PRESETS.find(p=>this.event&&p.id===this.event.preset)||PRESETS[0]}
  get selectedPreset(){return PRESETS.find(p=>p.id===this.create.preset)||PRESETS[0]}
  get overlayUrl():string{return window.location.origin+"/bundles/runback/graphics/scoreboard.html"}
  get publicBracketUrl():string{const base=this.publicBase.trim().replace(/\/$/,"")||window.location.origin;return this.event?base+"/bundles/runback/dashboard/share.html?event="+encodeURIComponent(this.event.id):""}
  get savedPlayers():any[]{return Object.values((this.$store.state as any).Runback.players||{})}
  get validResult():boolean{return !!this.selectedMatch&&this.scores.every(n=>Number.isInteger(n)&&n>=0&&n<=this.selectedMatch!.ft)&&Math.max(...this.scores)===this.selectedMatch.ft&&this.scores[0]!==this.scores[1]}
  get modalOpen():boolean{return !!(this.newEvent||this.startDialog||this.selectedMatch||this.reportDialog||this.undoDialog||this.endDialog||this.deleteEventDialog||this.seedPlayer||this.removePlayer||this.editEntry)}
  @Watch("modalOpen") onModal(open:boolean):void{if(open){this.previousFocus=document.activeElement as HTMLElement;this.$nextTick(()=>{const el=this.$el.querySelector('.org-modal input, .org-modal button') as HTMLElement;if(el)el.focus()})}else if(this.previousFocus)this.previousFocus.focus()}
  onKey(e:KeyboardEvent):void{
    if(!this.modalOpen)return
    if(e.key==="Escape"){if(this.reportDialog)this.reportDialog=false;else{this.newEvent=false;this.startDialog=false;this.undoDialog=false;this.endDialog=false;this.deleteEventDialog=false;this.seedPlayer="";this.removePlayer=null;this.editEntry=null;this.matchId=""}return}
    if(e.key!=="Tab")return
    const dialogs=this.$el.querySelectorAll('.org-modal');const dialog=dialogs[dialogs.length-1]
    const elements=Array.from(dialog.querySelectorAll<HTMLElement>('button:not([disabled]), input:not([disabled]), select:not([disabled]), textarea:not([disabled]), summary, a[href]')).filter(el=>el.offsetParent!==null)
    const first=elements[0],last=elements[elements.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}
  }
  occupied(station:string):boolean{return this.state.events.some(e=>(e.operations&&e.operations.unavailable.includes(station))||e.matches.some(m=>m.status==="playing"&&m.station===station))}
  name(id:string):string{return this.event&&id?(this.event.entrants.find(p=>p.id===id)||{name:"Unknown player"}).name:"To be decided"}
  initials(name:string):string{return name.split(/\s+/).map(s=>s[0]).slice(0,2).join("").toUpperCase()}
  statusLabel(m:Match):string{return ({ready:"Ready",playing:m.station||"Playing",done:m.reason?"Forfeit":"Completed",bye:"Bye",waiting:"Waiting",skipped:"Not needed"})[m.status]}
  sourceLabel(m:Match,i:number):string{const s=m.sources[i];return s.kind==="player"?(s.id?this.name(s.id):"Bye"):s.kind==="pool"?`Pool ${s.id} · place ${s.place||1}`:`${s.kind==="winner"?"Winner":"Loser"} of ${s.id}`}
  time(value:string):string{return new Date(value).toLocaleString()}
  @Watch("eventMenu") onEventMenu(open:boolean):void{if(open)this.eventSearch="";this.$nextTick(()=>{const el=this.$el.querySelector(open?'#event-menu input':'.event-picker-trigger') as HTMLElement;if(el)el.focus()})}
  @Watch("tab") onTab():void{this.page=1;this.error="";if(this.tab==="setup")this.syncSettings()}
  selectEvent():void{this.page=1;this.matchId="";this.search="";this.matchSearch="";this.bracketSection="";this.syncSettings();try{localStorage.setItem("runback-event",this.eventId)}catch(_){}}
  syncSettings():void{if(this.event){this.settingsRevision=this.state.revision;this.settingsForm={name:this.event.name,venue:this.event.venue,date:this.event.date,format:this.event.format,ft:this.event.ft,finalFt:this.event.finalFt,longSets:this.event.longSets,poolCount:this.event.poolCount||0,poolAdvance:this.event.poolAdvance||2,finalFormat:this.event.finalFormat||"double"};this.stationText=this.event.stations.join("\n")}}
  onChange(value:Organizer):void{if(!value)return;this.state=JSON.parse(JSON.stringify(value));this.loaded=true;if(!this.eventId||!this.event)this.eventId=this.state.events.length?this.state.events[this.state.events.length-1].id:""}
  onDisconnect():void{this.connected=false}
  onConnect():void{this.connected=true}
  mounted():void{
    document.addEventListener("keydown",this.onKey)
    try{this.eventId=localStorage.getItem("runback-event")||""}catch(_){}
    try{this.publicBase=localStorage.getItem("runback-public-base")||""}catch(_){}
    this.rep=nodecg.Replicant("Organizer");this.rep.on("change",this.onChange)
    if(this.rep.value)this.onChange(this.rep.value)
    const socket=(nodecg as any).socket;if(socket){this.connected=socket.connected;socket.on("disconnect",this.onDisconnect);socket.on("connect",this.onConnect)}
  }
  beforeDestroy():void{document.removeEventListener("keydown",this.onKey);if(this.rep)this.rep.removeListener("change",this.onChange);clearTimeout(this.noticeTimer);const socket=(nodecg as any).socket;if(socket){socket.removeListener("disconnect",this.onDisconnect);socket.removeListener("connect",this.onConnect)}}
  flash(message:string):void{this.notice=message;clearTimeout(this.noticeTimer);this.noticeTimer=setTimeout(()=>this.notice="",3500)}
  async command(action:string,data:any={}):Promise<any>{
    if(this.busy)return null;if(!this.connected){this.error="Reconnect to the local server before making changes.";return null}
    this.busy=true;this.error=""
    try {
      const revision=["score","report"].includes(action)?this.editRevision:action==="settings"?this.settingsRevision:this.state.revision
      let timeout:any
      let result:any
      try {result=await Promise.race([nodecg.sendMessage("organizer:command",{revision,action,eventId:this.eventId,data}),new Promise((_,reject)=>{timeout=setTimeout(()=>reject(new Error("Server response timed out. Refresh and check whether the change saved before retrying.")),10000)})])}finally{clearTimeout(timeout)}
      // Wait for the server's replicated revision before permitting the next edit.
      await new Promise<void>((resolve,reject)=>{let elapsed=0;const tick=setInterval(()=>{elapsed+=25;if(this.state.revision>=result.revision){clearInterval(tick);resolve()}else if(elapsed>5000){clearInterval(tick);reject(new Error("Saved, but the view is still reconnecting. Refresh before editing again."))}},25)})
      this.flash(action==="stream"?"Match sent to OBS":action==="report"?"Result recorded. Bracket updated.":"Saved")
      this.editRevision=this.state.revision;if(action==="settings")this.settingsRevision=this.state.revision
      return result
    }catch(e){this.error=(e as any).message||String(e);return null}finally{this.busy=false}
  }
  async createEvent():Promise<void>{const r=await this.command("create",this.create);if(r){this.eventId=r.eventId;this.newEvent=false;this.tab="players";this.create={name:"",preset:"local",venue:"",date:"",poolCount:0,poolAdvance:2,finalFormat:"double"};this.selectEvent()}}
  async addPlayer():Promise<void>{if(await this.command("addPlayers",{players:[this.playerForm]}))this.playerForm={name:"",team:"",country:"",discordId:""}}
  async importPlayers():Promise<void>{try{const players=parseRoster(this.bulk);if(await this.command("addPlayers",{players}))this.bulk=""}catch(e){this.error=(e as Error).message}}
  async readRoster(e:Event):Promise<void>{const input=e.target as HTMLInputElement;const file=input.files&&input.files[0];if(file){if(file.size>1024*1024){this.error="Roster file must be smaller than 1 MB.";return}this.bulk=await file.text()}input.value=""}
  async importSaved():Promise<void>{await this.command("addPlayers",{players:this.savedPlayers.map(p=>({name:p.gamertag,team:p.team,country:p.country,discordId:""}))})}
  async editPlayer():Promise<void>{if(await this.command("editPlayer",this.editEntry))this.editEntry=null}
  async changeSeed():Promise<void>{if(await this.command("seed",{playerId:this.seedPlayer,position:this.seedPosition}))this.seedPlayer=""}
  async deletePlayer():Promise<void>{if(this.removePlayer&&await this.command("removePlayer",{playerId:this.removePlayer.id}))this.removePlayer=null}
  async startEvent():Promise<void>{if(await this.command("start")){this.startDialog=false;this.tab="overview"}}
  async saveSettings():Promise<void>{await this.command("settings",{...this.settingsForm,stations:this.stationText.split(/\r?\n/).map(s=>s.trim()).filter(Boolean)})}
  openMatch(m:Match):void{if(this.event&&this.event.ended)return;this.editRevision=this.state.revision;this.matchId=m.id;this.scores=m.scores.slice();this.station=m.station||this.freeStations[0]||"";this.forfeit=-1;this.forfeitReason=""}
  async endTournament():Promise<void>{if(await this.command("endEvent")){this.endDialog=false;this.matchId="";this.reportDialog=false}}
  async deleteTournament():Promise<void>{if(await this.command("deleteEvent")){this.deleteEventDialog=false;this.matchId="";this.selectEvent();this.flash("Tournament deleted.")}}
  async swapSides(m:Match):Promise<void>{if(await this.command("swapSides",{matchId:m.id})&&this.matchId===m.id)this.scores=[this.scores[1],this.scores[0]]}
  async saveScore():Promise<void>{await this.command("score",{matchId:this.matchId,scores:this.scores})}
  async reportResult():Promise<void>{if(await this.command("report",{matchId:this.matchId,scores:this.scores,forfeit:this.forfeit,reason:this.forfeitReason})){this.reportDialog=false;this.matchId=""}}
  async undo():Promise<void>{if(await this.command("undo"))this.undoDialog=false}
  async copyUrl():Promise<void>{try{await navigator.clipboard.writeText(this.overlayUrl);this.copied=true;setTimeout(()=>this.copied=false,2500)}catch(_){this.error="Copy the displayed URL manually; clipboard access is unavailable."}}
  async copyBracketUrl():Promise<void>{if(!this.publicBracketUrl)return;try{await navigator.clipboard.writeText(this.publicBracketUrl);this.bracketCopied=true;this.flash("Live bracket link copied. Paste it into Discord or a browser.");setTimeout(()=>this.bracketCopied=false,2500)}catch(_){this.error="Copy this link from the address bar after opening the public bracket."}}
  savePublicBase():void{try{if(this.publicBase.trim()){const url=new URL(this.publicBase.trim());if(!["http:","https:"].includes(url.protocol))throw new Error("Use an http:// or https:// public address.");this.publicBase=url.origin;localStorage.setItem("runback-public-base",this.publicBase)}else{localStorage.removeItem("runback-public-base");this.publicBase=""}}catch(e){this.error=(e as Error).message||"Enter a valid public URL."}}
  openBracketUrl():void{if(this.publicBracketUrl)window.open(this.publicBracketUrl,"_blank","noopener")}
  download(content:string,filename:string,type:string):void{const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement("a");a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
  exportBackup():void{if(this.event)this.download(JSON.stringify({runbackOrganizer:1,event:this.event},null,2),"runback-event-backup.json","application/json")}
  openHistoryEvent(id:string,view:string="overview"):void{this.eventId=id;this.tab=view;this.selectEvent()}
  exportHistoryEvent(id:string):void{const e=this.state.events.find(item=>item.id===id);if(!e)return;const safe=e.name.trim().replace(/[^a-z0-9-_]+/gi,"-").replace(/^-|-$/g,"").slice(0,48)||"tournament";this.download(JSON.stringify({runbackOrganizer:1,event:e},null,2),`runback-${safe}-backup.json`,"application/json")}
  exportResults():void{const cell=(s:any)=>'"'+String(s).replace(/^[=+@\-]/,"'$&").replace(/"/g,'""')+'"';const rows=[["place","player","team","country","set_wins","set_losses"],...this.rankings.map(r=>{const p=this.event!.entrants.find(p=>p.id===r.id)!;return [r.place,p.name,p.team,p.country,r.wins,r.losses]})];this.download(rows.map(r=>r.map(cell).join(",")).join("\r\n"),"runback-results.csv","text/csv;charset=utf-8")}
  async restore(e:Event):Promise<void>{const input=e.target as HTMLInputElement;const file=input.files&&input.files[0];if(!file)return;try{if(file.size>4*1024*1024)throw new Error("Backup must be smaller than 4 MB.");const data=JSON.parse(await file.text());const r=await this.command("restore",data);if(r){this.eventId=r.eventId;this.tab="overview";this.selectEvent()}}catch(err){this.error=(err as Error).message}input.value=""}
  async demo():Promise<void>{const r=await this.command("create",{name:"Sample · Saturday Night Tekken",preset:"local",venue:"Example venue"});if(!r)return;this.eventId=r.eventId;const names=["Juniper","Nightshift","Kite","Static","Mako","Ember","Atlas","Echo","Nova","Violet","Orbit","Fable","Jett","Sable","Rune","Flint"];if(!await this.command("addPlayers",{players:names.map(name=>({name,team:"",country:""}))}))return;await this.command("checkAll");await this.command("start");this.tab="overview";this.selectEvent();this.flash("Sample event created with fictional players.")}
}

export function parseRoster(input:string):Array<{name:string;team:string;country:string}>{
  if(!input.trim())throw new Error("Paste at least one player.")
  const delimiter=input.includes("\t")?"\t":",";const rows:string[][]=[];let row:string[]=[];let cell="";let quoted=false
  for(let i=0;i<input.length;i++){const c=input[i];if(c==='"'){if(quoted&&input[i+1]==='"'){cell+='"';i++}else quoted=!quoted}else if(!quoted&&c===delimiter){row.push(cell.trim());cell=""}else if(!quoted&&(c==='\n'||c==='\r')){if(c==='\r'&&input[i+1]==='\n')i++;row.push(cell.trim());if(row.some(Boolean))rows.push(row);row=[];cell=""}else cell+=c}
  if(quoted)throw new Error("CSV has an unclosed quote.");row.push(cell.trim());if(row.some(Boolean))rows.push(row)
  if(rows[0]&&/^(name|gamertag|player)$/i.test(rows[0][0]))rows.shift()
  if(rows[0]&&/^(discord|discordid|discord_id)$/i.test(rows[0][3]||""))rows.shift()
  return rows.map(r=>({name:r[0]||"",team:r[1]||"",country:r[2]||"",discordId:r[3]||""}))
}
</script>




